#!/usr/bin/env node
// SPDX-License-Identifier: Apache-2.0
// scripts/check-arc42-slots.mjs — generated by arbiter (INV-144).
// arc42 slot-completeness runner for this project. Delegates to `arbiter doc-set --arc42` via npx
// (no local install, no `yaml` dep — the engine runs inside arbiter's own environment against this
// repo, same shape as check-doc-set.mjs.ejs and check-doc-freshness.mjs.ejs).
//
// The skeletons the audit compares against live in arbiter, not here: this project is held to the
// arc42 skeleton its own tier column receives, so a section deleted from the architecture document
// is reported as the structural gap it is rather than passing unnoticed.
//
// Usage: node scripts/check-arc42-slots.mjs [--json] [--update-baseline]
//
// Exit codes (INV-53): 0=every required slot present and the hollow-section count within baseline,
// 1=violation, 2=ERROR. On the FIRST clean run, with no scripts/data/arc42-baseline.json, the gate
// WRITES the hollow-section count it measured (creating scripts/data/) instead of failing — a
// freshly generated arc42 is hollow by construction, and a gate that made `arbiter init` produce a
// red repo would only teach people to delete it. Every run after that is a ratchet: the count may
// fall, never rise. Persisting matters: an earlier version only tolerated the count in memory, so
// no generated project ever grew a baseline and the ratchet never armed anywhere.
import { spawnSync } from 'node:child_process'

const args = process.argv.slice(2)

const result = spawnSync('npx', ['--no-install', 'arbiter', 'doc-set', '--arc42', ...args], {
  stdio: 'inherit',
  encoding: 'utf-8',
})

if (result.error) {
  process.stderr.write(`[arc42-slots] spawn error: ${result.error.message}\n`)
  process.exit(2)
}

process.exit(result.status ?? 1)
